import requests, json, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026年6月17日"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "今日 5 品牌均无新品上架或状态变更，各品牌监控状态如下："
                }
            },
            {"tag": "hr"},
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**🔵 海信 Hisense**\n产品型号与基线一致，无新增型号。Featured 产品：HRCD640TBW、HRCD640TSW、HRBM503E、HRCD483TBW 均在基线中。"
                }
            },
            {"tag": "hr"},
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**🔵 美的 Midea**\n官网显示 15 款产品，与基线一致。3 款 Coming Soon 型号状态未变：\n• MDRT580MTF45AP (413L Top Mount) — 仍为 Coming Soon\n• MDRS925FIM45AP (700L Side by Side) — 仍为 Coming Soon\n• MDRF923FIM45AP (706L Quad Door) — 仍为 Coming Soon"
                }
            },
            {"tag": "hr"},
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**🔵 三星 Samsung**\n通过搜索引擎巡检，未发现三星澳洲 2026 年冰箱新品发布信息。samsung.com/au/refrigerators 页面正常可访问。"
                }
            },
            {"tag": "hr"},
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**🔵 LG**\n通过搜索引擎巡检，未发现 LG 澳洲冰箱新品信息。LG 官网有反爬保护，无法直接抓取产品列表。"
                }
            },
            {"tag": "hr"},
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**🔵 西屋 Westinghouse**\n产品列表页抽取 12 款型号，与基线记录一致。无新增型号或品类变更。"
                }
            },
            {"tag": "hr"},
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**⚠️ 重点关注项（持续监控）**\n• 美的 3 款 Coming Soon 型号状态\n• 海信 ⭐New 标记型号是否有新增\n• 三星/LG 是否有新品发布"
                }
            },
            {"tag": "hr"},
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook_url, json=card, timeout=15)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

